CREATE TABLE school (id TEXT PRIMARY KEY CHECK(id='school'), name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Africa/Addis_Ababa', address TEXT NOT NULL DEFAULT '', settings TEXT NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT, roles TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE TABLE academic_year (id TEXT PRIMARY KEY, label TEXT NOT NULL UNIQUE);
CREATE TABLE term (id TEXT PRIMARY KEY, year_id TEXT NOT NULL REFERENCES academic_year(id), label TEXT NOT NULL, UNIQUE(year_id,label));
CREATE TABLE grade (id TEXT PRIMARY KEY, label TEXT NOT NULL UNIQUE, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE section (id TEXT PRIMARY KEY, grade_id TEXT NOT NULL REFERENCES grade(id), label TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(grade_id,label));
CREATE TABLE student (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE enrollment (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES student(id), year_id TEXT NOT NULL REFERENCES academic_year(id), section_id TEXT NOT NULL REFERENCES section(id), active INTEGER NOT NULL DEFAULT 1, UNIQUE(student_id,year_id));
CREATE TABLE subject (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE);
CREATE TABLE offering (id TEXT PRIMARY KEY, grade_id TEXT NOT NULL REFERENCES grade(id), subject_id TEXT NOT NULL REFERENCES subject(id), maximum NUMERIC NOT NULL CHECK(maximum>0), weight NUMERIC NOT NULL CHECK(weight>0), required INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, UNIQUE(grade_id,subject_id));
CREATE TABLE assignment (id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL REFERENCES users(id), term_id TEXT NOT NULL REFERENCES term(id), section_id TEXT NOT NULL REFERENCES section(id), offering_id TEXT NOT NULL REFERENCES offering(id), UNIQUE(term_id,section_id,offering_id));
CREATE TABLE scope_state (id TEXT PRIMARY KEY, term_id TEXT NOT NULL REFERENCES term(id), section_id TEXT NOT NULL REFERENCES section(id), revision INTEGER NOT NULL DEFAULT 0, UNIQUE(term_id,section_id));
CREATE TABLE import_batch (id TEXT PRIMARY KEY, assignment_id TEXT REFERENCES assignment(id), kind TEXT NOT NULL DEFAULT 'MARKS', actor_id TEXT NOT NULL REFERENCES users(id), source_key TEXT NOT NULL, file_hash TEXT NOT NULL, filename TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, scope_revision INTEGER NOT NULL, correction_reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, committed_at TEXT, UNIQUE(assignment_id,file_hash));
CREATE TABLE import_row (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES import_batch(id), line_number INTEGER NOT NULL, enrollment_id TEXT REFERENCES enrollment(id), raw_cells TEXT NOT NULL, value NUMERIC, reason TEXT, errors TEXT NOT NULL, warnings TEXT NOT NULL);
CREATE TABLE score (id TEXT PRIMARY KEY, enrollment_id TEXT NOT NULL REFERENCES enrollment(id), term_id TEXT NOT NULL REFERENCES term(id), offering_id TEXT NOT NULL REFERENCES offering(id), value NUMERIC NOT NULL CHECK(value>=0), source_row_id TEXT REFERENCES import_row(id), actor_id TEXT NOT NULL REFERENCES users(id), revision INTEGER NOT NULL, effective INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX score_effective ON score(enrollment_id,term_id,offering_id) WHERE effective=1;
CREATE TABLE score_exception (id TEXT PRIMARY KEY, enrollment_id TEXT NOT NULL REFERENCES enrollment(id), term_id TEXT NOT NULL REFERENCES term(id), offering_id TEXT NOT NULL REFERENCES offering(id), assignment_id TEXT REFERENCES assignment(id), source_row_id TEXT REFERENCES import_row(id), kind TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', remark TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE UNIQUE INDEX exception_active ON score_exception(enrollment_id,term_id,offering_id) WHERE status!='RESOLVED';
CREATE TABLE exception_resolution (id TEXT PRIMARY KEY, exception_id TEXT NOT NULL REFERENCES score_exception(id), action TEXT NOT NULL, value NUMERIC, justification TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE result_run (id TEXT PRIMARY KEY, term_id TEXT NOT NULL REFERENCES term(id), section_id TEXT NOT NULL REFERENCES section(id), revision INTEGER NOT NULL, scope_revision INTEGER NOT NULL, school_revision INTEGER NOT NULL, status TEXT NOT NULL, fingerprint TEXT NOT NULL, policy TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), approved_by TEXT REFERENCES users(id), approved_at TEXT, created_at TEXT NOT NULL, supersedes_id TEXT REFERENCES result_run(id), UNIQUE(term_id,section_id,revision));
CREATE TABLE student_result (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES result_run(id), enrollment_id TEXT NOT NULL REFERENCES enrollment(id), student_code TEXT NOT NULL, full_name TEXT NOT NULL, total NUMERIC NOT NULL, max_total NUMERIC NOT NULL, average NUMERIC NOT NULL, section_rank INTEGER NOT NULL, grade_rank INTEGER, UNIQUE(run_id,enrollment_id));
CREATE TABLE result_mark (id TEXT PRIMARY KEY, student_result_id TEXT NOT NULL REFERENCES student_result(id), offering_id TEXT NOT NULL REFERENCES offering(id), subject_name TEXT NOT NULL, value NUMERIC NOT NULL, maximum NUMERIC NOT NULL, weight NUMERIC NOT NULL, source_score_id TEXT NOT NULL REFERENCES score(id));
CREATE TABLE report_template (id TEXT PRIMARY KEY, family_id TEXT NOT NULL, name TEXT NOT NULL, version INTEGER NOT NULL, file_key TEXT, file_type TEXT NOT NULL, page_width NUMERIC NOT NULL, page_height NUMERIC NOT NULL, fields TEXT NOT NULL, status TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(family_id,version));
CREATE TABLE report_batch (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES report_template(id), run_ids TEXT NOT NULL, status TEXT NOT NULL, options TEXT NOT NULL, progress INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL, error TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, completed_at TEXT, lease_until TEXT, zip_key TEXT);
CREATE TABLE report_file (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES report_batch(id), run_id TEXT NOT NULL REFERENCES result_run(id), storage_key TEXT NOT NULL, filename TEXT NOT NULL, page_count INTEGER NOT NULL, checksum TEXT NOT NULL, UNIQUE(batch_id,run_id));
CREATE TABLE audit_event (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE transaction_guard (id TEXT PRIMARY KEY, ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE rate_limit (id TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 1);
CREATE INDEX student_name_idx ON student(full_name);
CREATE INDEX import_history_idx ON import_batch(assignment_id,created_at);
CREATE INDEX exception_scope_idx ON score_exception(term_id,status);
CREATE INDEX result_scope_idx ON result_run(term_id,section_id,revision);
CREATE INDEX audit_created_idx ON audit_event(created_at);
